def control_Alice(rnsForAWG=([1] * 1 + [1] * 9) * 400, globalDelay=0.0, onoff=[1, 0, 1, 0], V=0.0, rnsType=['ref'] * 140 + ['gap'] * 30 + ['signal'] * 230, syncChannel=4, reversePatternPM1=[1], precompensatePM1=['linear', 0, 0], basecode=0.0):
    # Encoder 的定义: AWG CH1 -> Reference AM; AWG CH2 -> Decoy & Z AM; AWG CH3 -> PM1; AWG CH4 -> PM2;
    encoder = worker_main.TF_AWGEncoder_Alice
    if not isinstance(rnsForAWG, str): globalDelay = globalDelay % (10 * len(rnsForAWG))
    encoder.configure('sampleRate', 12e9)  # 采样率  不动
    encoder.configure('waveformLength', None)
    encoder.configure('waveformUnitLength', 60)
    encoder.configure('randomNumbers', rnsForAWG)  # rnsBobForAWG)
    encoder.configure('widthAM1', [1.2, 1.2])  # [signal, reference]
    encoder.configure('widthPM1', 5)
    encoder.configure('delayAM1', globalDelay)
    encoder.configure('delayPM1', globalDelay - 35)
    encoder.configure('ampAM1', [0.5, 0.546, 0.595, 0.595, 1.0, 1.0])  # 这是原来的
    encoder.configure('biasAM1', [0.5] * 5)  # 这是原来的
    encoder.configure('reversePatternAM1', [0.93, -1] * 700 + [1, -1] * 1300)
    encoder.configure('ampPM1', [i / 16 * V + basecode for i in range(16)])  # PM半波电压

    encoder.configure('precompensatePM1', precompensatePM1)
    encoder.configure('reversePatternPM1', reversePatternPM1)

    # 关闭通道
    if onoff[0] == 0:
        encoder.configure('ampAM1', O=0, X=0, Y=0, Z=0, Ref=0)
        encoder.configure('biasAM1', O=0, X=0, Y=0, Z=0, Ref=0)
    if onoff[2] == 0:
        encoder.setV2Pi('PM1', 0)

    # 生成波形
    waveforms = encoder.generateNewWaveform()

    # 给处理程序的信息：随机数、通道、周期
    pulsePeriod = 5000
    tdc.configureAnalyser('TFQKDEncoding', {'TriggerChannel': 1, 'RandomNumbers': rnsForAWG, 'SignalChannel': 4, 'Period': pulsePeriod})  # 网页Encoding
    rnsForSync = [1 if rnsType[i] == 'signal' else 100 for i in range(len(rnsType))]
    tdc.configureAnalyser('TFQKDSyncAlice', {'SignalChannel': syncChannel, 'Period': pulsePeriod, 'RandomNumbers': Alice_TDC, 'BinCount': 100})  # 用于时钟同步的通道数据
    tdc.configureAnalyser('TFQKDSyncAliceMonitor', {'SignalChannel': syncChannel, 'RandomNumbers': rnsForSync, 'Period': pulsePeriod})  # 用于时钟同步的通道数据
    tdc.configureAnalyser('QKDQBER', {'AliceRandomNumbers': Alice_TDC})  # 给后处理

def control_Bob(rnsForAWG=([1] * 1 + [1] * 9) * 400, globalDelay=0.0, onoff=[1, 0, 1, 0], V=0.0, rnsType=['ref'] * 140 + ['gap'] * 30 + ['signal'] * 230, syncChannel=5, reversePatternPM1=[1], precompensatePM1=['linear', 0, 0], basecode=0.0):
    # Bob的相关控制
    # Encoder 的定义: AWG CH1 -> Reference AM; AWG CH2 -> Decoy & Z AM; AWG CH3 -> PM1; AWG CH4 -> PM2;
    encoder = worker_main.TF_AWGEncoder_Bob
    if not isinstance(rnsForAWG, str): globalDelay = globalDelay % (10 * len(rnsForAWG))
    encoder.configure('sampleRate', 12e9)  # 采样率  不动
    encoder.configure('waveformLength', None)
    encoder.configure('waveformUnitLength', 60)
    encoder.configure('randomNumbers', rnsForAWG)  # rnsBobForAWG)
    encoder.configure('widthAM1', [1.2, 1.2])  # [signal, reference]
    encoder.configure('widthPM1', 5)
    encoder.configure('delayAM1', globalDelay)
    encoder.configure('delayPM1', globalDelay - 38.2)  # 老放大器  - 38.2  # 新放大器 -38.9
    # encoder.configure('ampAM1', [0.5, 0.588, 0.686, 0.686, 1.0, 1.0])  # 这是原来的
    encoder.configure('ampAM1', [0.5, 0.543, 0.597, 0.597, 1.0, 1.0])  # 这是原来的
    encoder.configure('biasAM1', [0.5] * 5)  # 这是原来的
    encoder.configure('reversePatternAM1', [1, -1] * 700 + [1, -1] *1300)
    encoder.configure('ampPM1', [i / 16 * V + basecode for i in range(16)])  # PM半波电压

    encoder.configure('precompensatePM1', precompensatePM1)
    encoder.configure('reversePatternPM1', reversePatternPM1)

    # 关闭通道
    if onoff[0] == 0:
        encoder.configure('ampAM1', O=0, X=0, Y=0, Z=0, Ref=0)
        encoder.configure('biasAM1', O=0, X=0, Y=0, Z=0, Ref=0)
    if onoff[2] == 0:
        encoder.setV2Pi('PM1', 0)

    # 生成波形
    waveforms = encoder.generateNewWaveform()

    # 给处理程序的信息：随机数、通道、周期
    pulsePeriod = 5000
    tdc.configureAnalyser('TFQKDEncoding2', {'TriggerChannel': 1, 'RandomNumbers': rnsForAWG, 'SignalChannel': 5, 'Period': pulsePeriod})  # 网页Encoding2.0兼容
    rnsForSync = [1 if rnsType[i] == 'signal' else 100 for i in range(len(rnsType))]
    tdc.configureAnalyser('TFQKDSyncBob', {'SignalChannel': syncChannel, 'Period': pulsePeriod, 'RandomNumbers': Bob_TDC, 'BinCount': 100})  # 用于时钟同步的通道数据
    tdc.configureAnalyser('TFQKDSyncBobMonitor', {'SignalChannel': syncChannel, 'RandomNumbers': rnsForSync, 'Period': pulsePeriod})  # 用于时钟同步的通道数据
    tdc.configureAnalyser('QKDQBER', {'BobRandomNumbers': Bob_TDC})  # 给后处理


def runBob():
    VB=0.545
    rnsType=['ref'] * 1400 + ['gap'] * 300 + ['signal'] * 2300

    # Bob随机数
    rnsForAWG_Bob = Bob_AWG
    # rnsForAWG_Bob = [64] * 1 + [0] * (800 - 1)

    reversePatternPM1 = np.loadtxt(os.path.join(os.path.dirname(__file__), f"waveform_c1_random1.txt"))
    ######### 转换小数位数避免AWG服务内存溢出 ##########
    reversePatternPM1 = ((reversePatternPM1 * 10000).astype(np.int32).astype(np.float32) / 10000).tolist()

    control_Bob(rnsForAWG=rnsForAWG_Bob, globalDelay=0.0, onoff=[1, 0, 1, 0], V=VB, rnsType=rnsType, syncChannel=5,
                reversePatternPM1=reversePatternPM1, precompensatePM1=['linear', 0.1, 0], basecode=0.228125)

def runAlice():
    VA=0.55
    rnsType=['ref'] * 1400 + ['gap'] * 300 + ['signal'] * 2300

    # Alice随机数
    rnsForAWG_Alice = Alice_AWG
    # rnsForAWG_Alice = [64] * 1 + [0] * (800 - 1)

    reversePatternPM1 = np.loadtxt(os.path.join(os.path.dirname(__file__), f"waveform_c1_random2.txt"))
    ######### 转换小数位数避免AWG服务内存溢出 ##########
    reversePatternPM1 = ((reversePatternPM1 * 10000).astype(np.int32).astype(np.float32) / 10000).tolist()

    control_Alice(rnsForAWG=rnsForAWG_Alice, globalDelay=0.0, onoff=[1, 0, 1, 0], V=VA, rnsType=rnsType, syncChannel=4, 
                    reversePatternPM1=reversePatternPM1, precompensatePM1=['linear', 0.1, 0], basecode=0.228125)

def fetchDelays():
    result = storage.latest(collection='TFQKD_TDC', filter={'Data.TFQKDSyncAlice.Delay': 1, 'Data.TFQKDSyncBob.Delay': 1})
    return result["Data"]["TFQKDSyncAlice"]["Delay"], result["Data"]["TFQKDSyncBob"]["Delay"]

def runAliceWithCourseDelayFix():
    print('Running Alice with course delay fix')
    runAlice()
    time.sleep(5)
    delayAlice = fetchDelays()[0]
    print(f'Fetched delay for Alice: {delayAlice / 1000:.2f} ns')
    delayError = delayAlice / 1000  # ns; target delay is 2.5 ns
    if np.abs(delayError) > 1:
        delayCorrection = int(round(delayError))
        print(f'fix for {delayCorrection} ns and rerun Alice')
        worker.TF_AtomicClock_Alice.delay1PPS(delayCorrection if delayCorrection > 0 else 1000000000 + delayCorrection)
        time.sleep(2)
        runAlice()
    print('Finished running Alice with course delay fix')

def runBobWithCourseDelayFix():
    print('Running Bob with course delay fix')
    runBob()
    time.sleep(5)
    delayBob = fetchDelays()[1]
    print(f'Fetched delay for Bob: {delayBob / 1000:.2f} ns')
    delayError = delayBob / 1000  # ns; target delay is 0 ns
    if np.abs(delayError) > 1:
        delayCorrection = int(round(delayError))
        print(f'fix for {delayCorrection} ns and rerun Bob')
        worker.TF_AtomicClock_Bob.delay1PPS(delayCorrection if delayCorrection > 0 else 1000000000 + delayCorrection)
        time.sleep(2)
        runBob()
    print('Finished running Bob with course delay fix')

if __name__ == '__main__':
    # runAlice()
    runAliceWithCourseDelayFix()
    # runBob()
    runBobWithCourseDelayFix()